// BMI Assistant, staff side: answers questions about the BMI System's own
// records ("how many are obese this month", "who has the highest BMI",
// "show Reyes's records") with exact numbers computed here. The question
// is matched against known patterns; nothing is generated by the model,
// so a count or a name can never be made up. Pure functions only.

export type RecordRow = {
  personnelId: number;
  date: string; // YYYY-MM-DD
  height: number;
  weight: number;
  bmi: number;
  pnp: string | null;
};

export type PersonRow = {
  personnelId: number;
  rank: string | null;
  firstName: string;
  surname: string;
  sex: string | null;
  age: number | null;
  office: string | null;
};

type Range = { from: string | null; to: string | null; label: string };

const LIST_LIMIT = 15;
const round1 = (n: number) => Math.round(n * 10) / 10;
const word = (q: string, w: string) =>
  new RegExp(`(^|[^a-z0-9])${w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}($|[^a-z0-9])`, 'i').test(q);
const hasAny = (q: string, words: string[]) => words.some((w) => word(q, w));

// ---------- classification ----------

/** One spelling per class; old "Obese"/"Obese Class I" rows included. */
export function normalizeClass(pnp: string | null): string | null {
  if (!pnp) return null;
  const s = pnp.trim().toLowerCase().replace(/\s+/g, ' ');
  const roman: Record<string, string> = { i: '1', ii: '2', iii: '3' };
  const m = s.match(/^obese class (i{1,3}|\d)$/);
  if (m) return `Obese Class ${roman[m[1]] ?? m[1]}`;
  if (s === 'obese') return 'Obese';
  if (s === 'acceptable bmi' || s === 'acceptable') return 'Acceptable BMI';
  return pnp.trim().replace(/\b\w/g, (c) => c.toUpperCase());
}

const CLASS_ORDER = [
  'Severely Underweight', 'Underweight', 'Normal', 'Acceptable BMI', 'Overweight',
  'Obese', 'Obese Class 1', 'Obese Class 2', 'Obese Class 3',
];

/** Which classes a question is about, e.g. "obese" = every obese class. */
function classFilter(q: string): { label: string; match: (c: string | null) => boolean } | null {
  const c = (want: string[]) => (x: string | null) => !!x && want.includes(x);
  const cls = q.match(/obese class (i{1,3}|[123])\b/);
  if (cls) {
    const n = ({ i: '1', ii: '2', iii: '3' } as Record<string, string>)[cls[1]] ?? cls[1];
    return { label: `Obese Class ${n}`, match: c([`Obese Class ${n}`]) };
  }
  if (q.includes('severely underweight')) return { label: 'Severely Underweight', match: c(['Severely Underweight']) };
  if (hasAny(q, ['obese', 'obesity', 'mataba'])) {
    return { label: 'Obese (all classes)', match: (x) => !!x && x.startsWith('Obese') };
  }
  if (hasAny(q, ['overweight', 'sobra sa timbang'])) return { label: 'Overweight', match: c(['Overweight']) };
  if (hasAny(q, ['underweight', 'kulang sa timbang'])) return { label: 'Underweight', match: c(['Underweight', 'Severely Underweight']) };
  if (hasAny(q, ['acceptable'])) return { label: 'Acceptable BMI', match: c(['Acceptable BMI']) };
  if (hasAny(q, ['normal'])) return { label: 'Normal', match: c(['Normal']) };
  return null;
}

// ---------- time ----------

const MONTHS: [string[], number][] = [
  [['january', 'jan', 'enero'], 0], [['february', 'feb', 'pebrero'], 1],
  [['march', 'mar', 'marso'], 2], [['april', 'apr', 'abril'], 3],
  [['mayo'], 4], [['june', 'jun', 'hunyo'], 5], [['july', 'jul', 'hulyo'], 6],
  [['august', 'aug', 'agosto'], 7], [['september', 'sept', 'sep', 'setyembre'], 8],
  [['october', 'oct', 'oktubre'], 9], [['november', 'nov', 'nobyembre'], 10],
  [['december', 'dec', 'disyembre'], 11],
];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const iso = (y: number, m: number, d: number) => new Date(Date.UTC(y, m, d)).toISOString().slice(0, 10);

export function parseRange(q: string, today: string): Range | null {
  const [ty, tm, td] = today.split('-').map(Number);
  const month = (y: number, m: number): Range => ({
    from: iso(y, m, 1), to: iso(y, m + 1, 1), label: `${MONTH_NAMES[((m % 12) + 12) % 12]} ${new Date(Date.UTC(y, m, 1)).getUTCFullYear()}`,
  });

  if (hasAny(q, ['today', 'ngayon araw', 'ngayong araw'])) return { from: today, to: iso(ty, tm - 1, td + 1), label: 'today' };
  if (hasAny(q, ['yesterday', 'kahapon'])) return { from: iso(ty, tm - 1, td - 1), to: today, label: 'yesterday' };
  if (/this week|ngayong linggo/.test(q) || /last week|nakaraang linggo/.test(q)) {
    const dow = (new Date(Date.UTC(ty, tm - 1, td)).getUTCDay() + 6) % 7; // Monday = 0
    const monday = td - dow - (/last week|nakaraang linggo/.test(q) ? 7 : 0);
    return { from: iso(ty, tm - 1, monday), to: iso(ty, tm - 1, monday + 7), label: /last week|nakaraang/.test(q) ? 'last week' : 'this week' };
  }
  if (/this month|ngayong buwan/.test(q)) return month(ty, tm - 1);
  if (/last month|nakaraang buwan/.test(q)) return month(ty, tm - 2);
  if (/this year|ngayong taon/.test(q)) return { from: iso(ty, 0, 1), to: iso(ty + 1, 0, 1), label: String(ty) };
  if (/last year|nakaraang taon/.test(q)) return { from: iso(ty - 1, 0, 1), to: iso(ty, 0, 1), label: String(ty - 1) };

  const yearMatch = q.match(/\b(20\d\d)\b/);
  const year = yearMatch ? Number(yearMatch[1]) : null;
  for (const [names, m] of MONTHS) {
    if (hasAny(q, names)) return month(year ?? ty, m);
  }
  // "may" is an everyday word: only a month when clearly a date.
  if (/\b(in|of|noong) may\b|\bmay (20\d\d)\b/.test(q)) return month(year ?? ty, 4);
  if (year) return { from: iso(year, 0, 1), to: iso(year + 1, 0, 1), label: String(year) };
  return null;
}

const inRange = (date: string, r: Range | null) =>
  !r || ((r.from === null || date >= r.from) && (r.to === null || date < r.to));

// ---------- people filters ----------

function acronym(name: string): string {
  return name.split(/\s+/).filter((w) => /^[A-Z]/.test(w)).map((w) => w[0]).join('').toLowerCase();
}

type PeopleFilter = { label: string[]; match: (p: PersonRow) => boolean };

function peopleFilter(q: string, people: PersonRow[]): PeopleFilter {
  const parts: { label: string; test: (p: PersonRow) => boolean }[] = [];

  if (hasAny(q, ['female', 'women', 'woman', 'babae'])) {
    parts.push({ label: 'female', test: (p) => (p.sex ?? '').toLowerCase().startsWith('f') });
  } else if (hasAny(q, ['male', 'men', 'man', 'lalaki'])) {
    parts.push({ label: 'male', test: (p) => (p.sex ?? '').toLowerCase().startsWith('m') });
  }

  const offices = [...new Set(people.map((p) => p.office).filter((o): o is string => !!o))];
  const office = offices.find((o) => {
    const lo = o.toLowerCase();
    const short = lo.replace(/^pnp\s+/, '');
    const ac = acronym(o);
    return q.includes(lo) || (short.length > 5 && q.includes(short)) || (ac.length >= 3 && word(q, ac));
  });
  if (office) parts.push({ label: office, test: (p) => p.office === office });

  const ranks = [...new Set(people.map((p) => p.rank).filter((r): r is string => !!r))]
    .sort((a, b) => b.length - a.length);
  const rank = ranks.find((r) => word(q, r.toLowerCase()));
  if (rank) parts.push({ label: rank, test: (p) => p.rank === rank });

  return { label: parts.map((p) => p.label), match: (p) => parts.every((x) => x.test(p)) };
}

function findPeopleByName(q: string, people: PersonRow[]): PersonRow[] {
  const bySurname = people.filter((p) => p.surname.length >= 3 && word(q, p.surname.toLowerCase()));
  if (bySurname.length <= 1) return bySurname;
  // Same surname: narrow by first name when given.
  const narrowed = bySurname.filter((p) => word(q, p.firstName.toLowerCase()));
  return narrowed.length ? narrowed : bySurname;
}

// ---------- helpers ----------

const fullName = (p: PersonRow | undefined) =>
  p ? [p.rank, p.firstName, p.surname].filter(Boolean).join(' ') : 'Unknown personnel';

/** Each person's latest assessment within the range. */
function latestPerPerson(recs: RecordRow[], r: Range | null): Map<number, RecordRow> {
  const out = new Map<number, RecordRow>();
  for (const rec of recs) {
    if (!inRange(rec.date, r)) continue;
    const cur = out.get(rec.personnelId);
    // recs are oldest first, so on the same date the later-saved row wins.
    if (!cur || rec.date >= cur.date) {
      out.set(rec.personnelId, rec);
    }
  }
  return out;
}

const listLines = (lines: string[]) =>
  lines.slice(0, LIST_LIMIT).map((l) => `- ${l}`).join('\n') +
  (lines.length > LIST_LIMIT ? `\n- ...and ${lines.length - LIST_LIMIT} more` : '');

function scopeText(r: Range | null, f: PeopleFilter) {
  const who = f.label.length ? ` (${f.label.join(', ')})` : '';
  return `${r ? r.label : 'all records'}${who}`;
}

// ---------- main ----------

/**
 * Answers a question about the records, or returns null when it is not a
 * records question (the assistant then answers it another way).
 */
export function answerRecordsQuestion(
  question: string,
  people: PersonRow[],
  records: RecordRow[],
  today: string,
): string | null {
  const q = question.toLowerCase().replace(/[?!.,]/g, ' ').replace(/\s+/g, ' ').trim();
  const byId = new Map(people.map((p) => [p.personnelId, p]));
  // Oldest first, so "latest" ties resolve to the later-saved row.
  const recs = [...records]
    .map((r) => ({ ...r, pnp: normalizeClass(r.pnp) }))
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  const range = parseRange(q, today);
  const filter = peopleFilter(q, people);
  const cls = classFilter(q);
  const inScope = (r: RecordRow) => inRange(r.date, range) && filter.match(byId.get(r.personnelId) ?? ({} as PersonRow));
  const scoped = recs.filter(inScope);
  const latest = [...latestPerPerson(scoped, null).values()];
  const scope = scopeText(range, filter);

  const isCount = hasAny(q, ['how many', 'ilan', 'number of', 'count', 'total', 'ilang']);
  const isAverage = hasAny(q, ['average', 'mean', 'avg', 'karaniwan']);
  const metric = hasAny(q, ['weight', 'timbang', 'heaviest', 'lightest']) ? 'weight'
    : hasAny(q, ['height', 'taas', 'tallest', 'shortest']) ? 'height' : 'bmi';
  const unit = metric === 'weight' ? ' kg' : metric === 'height' ? ' cm' : '';

  // 1. One person's records.
  const named = findPeopleByName(q, people);
  if (named.length && !isCount && !isAverage) {
    if (named.length > 1) {
      return `More than one personnel matches: ${named.map(fullName).join('; ')}. Add the first name to choose one.`;
    }
    const p = named[0];
    const theirs = recs.filter((r) => r.personnelId === p.personnelId && inRange(r.date, range)).reverse();
    if (!theirs.length) {
      return `${fullName(p)} has no assessment${range ? ` in ${range.label}` : ' on record'}.`;
    }
    const [last, prev] = theirs;
    const trend = prev
      ? `\nChange since ${prev.date}: ${round1(last.weight - prev.weight) > 0 ? '+' : ''}${round1(last.weight - prev.weight)} kg (BMI ${round1(prev.bmi)} to ${round1(last.bmi)}).`
      : '';
    const history = theirs.slice(0, 6).map((r) => `${r.date}: ${r.weight} kg, ${r.height} cm, BMI ${round1(r.bmi)} (${r.pnp ?? '-'})`);
    return `${fullName(p)}${p.office ? `, ${p.office}` : ''}${p.age ? `, age ${p.age}` : ''}: ${theirs.length} assessment(s)${range ? ` in ${range.label}` : ''}.\n` +
      `Latest (${last.date}): BMI ${round1(last.bmi)}, ${last.pnp ?? 'no classification'}.${trend}\n\nRecent assessments:\n${listLines(history)}`;
  }

  // 2. Who has not been assessed.
  if (/not (been )?(assessed|measured)|no assessment|without (an )?assessment|hindi pa|walang assessment|missing/.test(q)) {
    const assessed = new Set(scoped.map((r) => r.personnelId));
    const missing = people.filter((p) => filter.match(p) && !assessed.has(p.personnelId));
    if (!missing.length) return `Everyone${filter.label.length ? ` (${filter.label.join(', ')})` : ''} has an assessment in ${range ? range.label : 'the records'}.`;
    return `${missing.length} personnel have no assessment in ${scope}:\n${listLines(missing.map(fullName))}`;
  }

  // 3. Who improved / lost or gained the most.
  if (/improv|lost the most|most weight lost|gained the most|biggest (loss|gain)|pumayat|tumaba/.test(q)) {
    const gain = /gained|gain|tumaba/.test(q);
    const changes: { p: PersonRow | undefined; d: number; from: RecordRow; to: RecordRow }[] = [];
    for (const id of new Set(scoped.map((r) => r.personnelId))) {
      const theirs = scoped.filter((r) => r.personnelId === id);
      if (theirs.length < 2) continue;
      const from = theirs[theirs.length - 2];
      const to = theirs[theirs.length - 1];
      changes.push({ p: byId.get(id), d: round1(to.weight - from.weight), from, to });
    }
    const ranked = changes.filter((c) => (gain ? c.d > 0 : c.d < 0)).sort((a, b) => (gain ? b.d - a.d : a.d - b.d));
    if (!ranked.length) return `Nobody ${gain ? 'gained' : 'lost'} weight between their last two assessments in ${scope}.`;
    return `Biggest weight ${gain ? 'gain' : 'loss'} between each person's last two assessments (${scope}):\n` +
      listLines(ranked.map((c) => `${fullName(c.p)}: ${c.d > 0 ? '+' : ''}${c.d} kg (${c.from.weight} to ${c.to.weight} kg, BMI ${round1(c.from.bmi)} to ${round1(c.to.bmi)})`));
  }

  // 4. Highest / lowest / top N.
  const top = q.match(/\btop (\d{1,2})\b/);
  if (/highest|lowest|heaviest|lightest|tallest|shortest|pinakamataas|pinakamababa|pinakamabigat/.test(q) || top) {
    const low = /lowest|lightest|shortest|pinakamababa/.test(q);
    const n = top ? Math.min(Number(top[1]), LIST_LIMIT) : /\bwho\b|sino/.test(q) && !/\bare\b/.test(q) ? 1 : 5;
    const pool = cls ? latest.filter((r) => cls.match(r.pnp)) : latest;
    if (!pool.length) return `No assessments found for ${scope}.`;
    const sorted = [...pool].sort((a, b) => (low ? a[metric] - b[metric] : b[metric] - a[metric])).slice(0, n);
    const what = `${low ? 'Lowest' : 'Highest'} ${metric === 'bmi' ? 'BMI' : metric}`;
    return `${what}, by each personnel's latest assessment (${scope}${cls ? `, ${cls.label}` : ''}):\n` +
      listLines(sorted.map((r) => `${fullName(byId.get(r.personnelId))}: ${round1(r[metric])}${unit} (BMI ${round1(r.bmi)}, ${r.pnp ?? '-'}, ${r.date})`));
  }

  // 5. Averages.
  if (isAverage) {
    const pool = cls ? latest.filter((r) => cls.match(r.pnp)) : latest;
    if (!pool.length) return `No assessments found for ${scope}.`;
    const avg = round1(pool.reduce((s, r) => s + r[metric], 0) / pool.length);
    return `Average ${metric === 'bmi' ? 'BMI' : metric} is ${avg}${unit} across ${pool.length} personnel (each person's latest assessment; ${scope}${cls ? `, ${cls.label}` : ''}).`;
  }

  // 5b. Which offices/departments or ranks exist, or how many -- checked
  // before the generic count/list branches below so "how many departments
  // are there" does not fall through to a personnel headcount, and before
  // the model ever sees the question (it otherwise invents plausible-
  // sounding office/rank names instead of using the real ones on file).
  {
    const isOfficeWord = /\b(department|departments|office|offices|opisina|departamento)\b/.test(q);
    const isRankWord = /\brank(s)?\b|\branggo\b/.test(q);
    const wantsList = /\b(list|show|what|which|name|names|all|ano|anong|ilista)\b/.test(q);

    if ((isOfficeWord || isRankWord) && (isCount || wantsList)) {
      const category = isOfficeWord
        ? people.map((p) => p.office)
        : people.map((p) => p.rank);
      const counts = new Map<string, number>();
      for (const v of category) if (v) counts.set(v, (counts.get(v) ?? 0) + 1);
      const noun = isOfficeWord ? 'office(s)/department(s)' : 'rank(s)';
      const names = [...counts.keys()].sort();

      if (!names.length) return `No ${noun} are on record.`;

      // A classification word alongside ("...with obese personnel") asks
      // for a filtered cross-tab this cannot compute yet -- say so rather
      // than silently ignoring the filter and listing everyone.
      const hedge = cls
        ? ` (this does not yet filter by ${cls.label}; showing every ${isOfficeWord ? 'office' : 'rank'})`
        : '';

      if (isCount && !wantsList) {
        return `${names.length} ${noun} ${isOfficeWord ? 'are' : 'exist'} in the system${hedge}.`;
      }
      return `${names.length} ${noun} are in the system${hedge}:\n` +
        listLines(names.map((n) => `${n} (${counts.get(n)} personnel)`));
    }
  }

  // 6. Counts.
  if (isCount) {
    if (hasAny(q, ['assessment', 'assessments', 'measurement', 'measurements', 'records', 'record', 'measured', 'sukat'])) {
      const pool = cls ? scoped.filter((r) => cls.match(r.pnp)) : scoped;
      return `${pool.length} assessment(s) in ${scope}${cls ? ` classified ${cls.label}` : ''}, covering ${new Set(pool.map((r) => r.personnelId)).size} personnel.`;
    }
    if (cls) {
      const n = latest.filter((r) => cls.match(r.pnp)).length;
      return `${n} of ${latest.length} assessed personnel are ${cls.label} (by each person's latest assessment; ${scope}).`;
    }
    const registered = people.filter(filter.match);
    return `${registered.length} personnel are registered${filter.label.length ? ` (${filter.label.join(', ')})` : ''}; ${latest.length} of them have an assessment in ${range ? range.label : 'the records'}.`;
  }

  // 7. Lists by classification.
  if (cls && /\b(list|show|who|which|names|sino|ipakita|pakita)\b/.test(q)) {
    const pool = latest.filter((r) => cls.match(r.pnp)).sort((a, b) => b.bmi - a.bmi);
    if (!pool.length) return `Nobody is ${cls.label} in ${scope}.`;
    return `${pool.length} personnel are ${cls.label} (latest assessment; ${scope}):\n` +
      listLines(pool.map((r) => `${fullName(byId.get(r.personnelId))}: BMI ${round1(r.bmi)}, ${r.weight} kg (${r.date})`));
  }

  // 8. Summary / breakdown.
  if (/summary|breakdown|distribution|overview|statistic|stats|report|buod/.test(q)) {
    if (!latest.length) return `No assessments found for ${scope}.`;
    const counts = new Map<string, number>();
    for (const r of latest) counts.set(r.pnp ?? 'Unclassified', (counts.get(r.pnp ?? 'Unclassified') ?? 0) + 1);
    const rows = [...counts.entries()].sort((a, b) => CLASS_ORDER.indexOf(a[0]) - CLASS_ORDER.indexOf(b[0]));
    const avg = round1(latest.reduce((s, r) => s + r.bmi, 0) / latest.length);
    return `Summary for ${scope}: ${scoped.length} assessment(s) of ${latest.length} personnel, average BMI ${avg}.\nBy each person's latest classification:\n` +
      listLines(rows.map(([c, n]) => `${c}: ${n} (${Math.round((n / latest.length) * 100)}%)`));
  }

  // 9. When was the last assessment (in scope). Without this the model
  // invents a date instead of admitting it does not track real-time status.
  if (/\b(last|latest|most recent|huling)\b.*\b(assessment|measured|measurement|sukat)\b|\b(assessment|measured|measurement|sukat)\b.*\b(last|latest|most recent|huli)\b/.test(q)) {
    if (!scoped.length) return `No assessments found for ${scope}.`;
    const mostRecent = scoped[scoped.length - 1]; // recs/scoped are oldest-first
    const who = fullName(byId.get(mostRecent.personnelId));
    return `The most recent assessment on record (${scope}) was on ${mostRecent.date}, for ${who} (BMI ${round1(mostRecent.bmi)}, ${mostRecent.pnp ?? 'no classification'}).`;
  }

  return null;
}
